// One-time original fixture generator. Compile in a temporary Cargo project
// with djvu-rs = "=0.43.0"; run from the LibreMemo root with reading.djvu,
// second.djv, bundled.djvu as arguments. Not part of the app or build.
fn main() { let args:Vec<String>=std::env::args().collect(); let a=std::fs::read(&args[1]).unwrap(); let b=std::fs::read(&args[2]).unwrap(); let out=djvu_rs::djvm::merge(&[&a,&b]).unwrap(); std::fs::write(&args[3],out).unwrap(); let doc=djvu_rs::DjVuDocument::parse(&a).unwrap(); let pm=djvu_rs::djvu_render::render_pixmap(doc.page(0).unwrap(),&djvu_rs::djvu_render::RenderOptions{width:320,height:200,..Default::default()}).unwrap(); let color=djvu_rs::djvu_encode::PageEncoder::from_pixmap(&pm).with_quality(djvu_rs::djvu_encode::EncodeQuality::Photo).with_dpi(100).encode().unwrap();std::fs::write("tests/fixtures/djvu/photo.djvu",color).unwrap(); let mut bitmap=djvu_rs::Bitmap::new(320,200);for y in 30..160 {for x in 20..290 {if y%30<6||x<26 {bitmap.set_black(x,y);}}}let bw=djvu_rs::djvu_encode::PageEncoder::from_bitmap(&bitmap).with_dpi(100).encode().unwrap();std::fs::write("tests/fixtures/djvu/bilevel.djvu",bw).unwrap(); }
